CREATE OR REPLACE FUNCTION public.fn_email_owned() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ SELECT auth.uid() IS NOT NULL AND (EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) a WHERE a->>'method' IN ('otp','magiclink')) OR EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND confirmation_sent_at IS NOT NULL AND email_confirmed_at IS NOT NULL)) $$;
REVOKE ALL ON FUNCTION public.fn_email_owned() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fn_email_owned() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.fn_claim_referrer_leads() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE e text; n integer; BEGIN IF NOT public.fn_email_owned() THEN RETURN 0; END IF; SELECT lower(email) INTO e FROM auth.users WHERE id=auth.uid(); UPDATE public.leads SET referrer_user_id=auth.uid() WHERE referrer_user_id IS NULL AND lower(referrer_email)=e; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
DROP POLICY IF EXISTS "Referrers view own claimed leads" ON public.leads;
CREATE OR REPLACE FUNCTION public.fn_referrer_lead_summary() RETURNS TABLE(business_name text,lead_first_name text,status text,reward_amount numeric,reward_status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ SELECT b.name,split_part(btrim(l.lead_name),' ',1),l.status,w.amount,w.status FROM public.leads l JOIN public.businesses b ON b.id=l.business_id LEFT JOIN public.rewards w ON w.lead_id=l.id WHERE public.fn_email_owned() AND l.referrer_user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.fn_referrer_lead_summary() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fn_referrer_lead_summary() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.fn_my_referrals() RETURNS json LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE e text; BEGIN IF NOT public.fn_email_owned() THEN RETURN '[]'::json; END IF; SELECT lower(email) INTO e FROM auth.users WHERE id=auth.uid(); RETURN coalesce((SELECT json_agg(x) FROM (SELECT b.name AS business_name,b.slug,b.offer_amount AS reward,r.token,coalesce((SELECT json_agg(json_build_object('lead_first_name',split_part(btrim(l.lead_name),' ',1),'created_at',l.created_at,'status',CASE l.status WHEN 'in_progress' THEN 'quoted' WHEN 'closed_won' THEN 'closed' WHEN 'closed_lost' THEN 'lost' ELSE l.status END,'reward_amount',w.amount,'reward_status',CASE WHEN w.id IS NULL THEN NULL WHEN w.status='paid' THEN 'paid' ELSE 'owed' END) ORDER BY l.created_at DESC) FROM public.leads l LEFT JOIN public.rewards w ON w.lead_id=l.id WHERE l.referrer_id=r.id),'[]'::json) AS referrals FROM public.referrers r JOIN public.businesses b ON b.id=r.business_id WHERE lower(r.email)=e AND NOT coalesce(b.is_demo,false)) x),'[]'::json); END $$;
REVOKE EXECUTE ON FUNCTION public.fn_create_notification(uuid,text,text,text,uuid),public.fn_create_audit_entry(uuid,uuid,text,jsonb),public.fn_create_audit_entry(uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fn_create_notification(uuid,text,text,text,uuid),public.fn_create_audit_entry(uuid,uuid,text,jsonb),public.fn_create_audit_entry(uuid,text,jsonb) TO service_role;
DROP POLICY IF EXISTS "Referrers submit referrals" ON public.referrals;
DROP POLICY IF EXISTS "Business owners read referral attachments" ON storage.objects;
CREATE POLICY "Business owners read referral attachments" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='referral-attachments' AND EXISTS(SELECT 1 FROM public.referrals r JOIN public.businesses b ON b.id=r.business_id WHERE b.user_id=auth.uid() AND (storage.foldername(name))[1]=r.referrer_id::text));
ALTER TABLE public.businesses ADD COLUMN IF NOT EXISTS index_approved boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.fn_guard_is_verified() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ BEGIN IF coalesce(auth.role(),'')='service_role' OR auth.uid() IS NULL THEN RETURN NEW; END IF; IF TG_OP='INSERT' THEN NEW.is_verified:=false; NEW.index_approved:=false; RETURN NEW; END IF; IF NEW.is_verified IS DISTINCT FROM OLD.is_verified OR NEW.index_approved IS DISTINCT FROM OLD.index_approved THEN IF NOT public.has_role(auth.uid(),'admin') OR OLD.user_id=auth.uid() THEN RAISE EXCEPTION 'Only a super admin can change verification or indexing'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ SELECT (coalesce(auth.role(),'')='service_role' OR _user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin')) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
DROP POLICY IF EXISTS "Public offers viewable" ON public.offers;
CREATE POLICY "Public offers viewable" ON public.offers FOR SELECT USING((status='active' AND approval_status='approved' AND NOT public.fn_offer_is_restricted_category(category) AND EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=offers.business_id AND b.account_status<>'suspended' AND b.marketplace_listed AND NOT public.fn_offer_is_restricted_category(b.category))) OR EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=offers.business_id AND b.user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.business_trial_history(user_id uuid PRIMARY KEY,granted_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.business_trial_history TO service_role;
ALTER TABLE public.business_trial_history ENABLE ROW LEVEL SECURITY;
INSERT INTO public.business_trial_history(user_id) SELECT DISTINCT user_id FROM public.businesses WHERE pro_trial_ends_at IS NOT NULL ON CONFLICT DO NOTHING;
ALTER TABLE public.businesses ADD CONSTRAINT businesses_one_per_user UNIQUE(user_id);
DROP POLICY IF EXISTS "Owners manage business" ON public.businesses;
DROP POLICY IF EXISTS "Owners delete business" ON public.businesses;
CREATE OR REPLACE FUNCTION public.fn_guard_first_trial() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE n integer; BEGIN INSERT INTO public.business_trial_history(user_id) VALUES(NEW.user_id) ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; IF n=0 THEN NEW.pro_trial_ends_at:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER zzz_first_trial BEFORE INSERT ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.fn_guard_first_trial();
CREATE OR REPLACE FUNCTION public.fn_freeze_lead_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ BEGIN IF coalesce(auth.role(),'')<>'service_role' AND EXISTS(SELECT 1 FROM public.businesses WHERE id=OLD.business_id AND user_id=auth.uid()) AND (NEW.referrer_user_id IS DISTINCT FROM OLD.referrer_user_id OR NEW.status_token IS DISTINCT FROM OLD.status_token) THEN RAISE EXCEPTION 'Lead identity is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_freeze_lead_identity BEFORE UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.fn_freeze_lead_identity();
REVOKE EXECUTE ON FUNCTION public.fn_release_invite_code(text),public.email_queue_dispatch(),public.fn_check_duplicate_referral(uuid,uuid,text,text,integer),public.fn_is_suppressed(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fn_release_invite_code(text),public.email_queue_dispatch(),public.fn_check_duplicate_referral(uuid,uuid,text,text,integer),public.fn_is_suppressed(uuid,text,text) TO service_role;